import meta from './sprites.json'

/**
 * Sprite registry. Every image the game uses is listed in src/assets/sprites.json
 * (generated by tools/slice_sheet.py). To replace art: drop a new PNG with the same
 * key into public/assets/ and re-run the meta step — no code changes.
 */
export type SpriteKey = keyof typeof meta

export const SPRITES = meta as Record<SpriteKey, { w: number; h: number; ax: number; ay: number }>

export function spriteUrl(key: SpriteKey) {
  return `${import.meta.env.BASE_URL}assets/${key}.png`
}

export function hasSprite(key: string): key is SpriteKey {
  return key in SPRITES
}

